package com.trainflow.document;
import java.io.IOException; import java.util.*; import org.springframework.core.io.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/training-cases/{caseId}/documents") public class DocumentController {private final DocumentService service;public DocumentController(DocumentService service){this.service=service;}@GetMapping List<DocumentResponse> list(@PathVariable UUID caseId){return service.list(caseId);}@PostMapping("/initialize") List<DocumentResponse> initialize(@PathVariable UUID caseId){return service.initialize(caseId);}@PostMapping("/generate-all") GenerateAllResponse all(@PathVariable UUID caseId){return service.generateAll(caseId);}@PostMapping("/{type}/generate") DocumentResponse generate(@PathVariable UUID caseId,@PathVariable DocumentType type){return service.generate(caseId,type);}@GetMapping("/{type}/download") ResponseEntity<Resource> download(@PathVariable UUID caseId,@PathVariable DocumentType type)throws IOException{var file=service.download(caseId,type);return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+file.filename().replace("\"","")+"\"").contentLength(java.nio.file.Files.size(file.path())).body(new FileSystemResource(file.path()));}}
